-- 008_local_changes_to_live.sql
-- Carries the content/structure changes made on the LOCAL database since migration 002 over to the LIVE one.
-- Generated 2026-10-05 from a diff of local vs the 002 content snapshot.
--
-- Safe by design:
--   * never deletes a row and never touches comment / subscribe / poll_vote (visitor data)
--   * a post/sub-category BODY is replaced only if the live copy still equals the 002 snapshot
--     (compared by MD5). If you edited it on live since, it is left alone and listed in the report at the end.
--   * safe to run more than once; backs up every table it modifies first (bak_20261005_*)
-- Run:  mysql -u USER -p DBNAME < 008_local_changes_to_live.sql   (or import in phpMyAdmin)
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS bak_20261005_post AS SELECT * FROM post;
CREATE TABLE IF NOT EXISTS bak_20261005_sub_category AS SELECT * FROM sub_category;
CREATE TABLE IF NOT EXISTS bak_20261005_meta AS SELECT * FROM meta;
CREATE TABLE IF NOT EXISTS bak_20261005_author AS SELECT * FROM author;

-- 1. schema the new code expects
SET @has_aid := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='post' AND COLUMN_NAME='author_id');
SET @sql := IF(@has_aid=0, 'ALTER TABLE post ADD COLUMN author_id INT NULL, ADD INDEX idx_post_author (author_id)', 'SELECT 1');
PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
CREATE TABLE IF NOT EXISTS `site_setting` (
  `setting_key` VARCHAR(100) NOT NULL PRIMARY KEY,
  `setting_value` VARCHAR(255) NOT NULL DEFAULT '',
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO site_setting (setting_key, setting_value) VALUES ('cookies_section_enabled','0');

