-- 6. report: what still needs a manual look
SELECT 'posts still without the related-reading block (edited on live since 002, or not on this site)' AS check_name, COUNT(*) AS n FROM post WHERE status='published' AND post_desc NOT LIKE '%imp-related-reading%';
SELECT uri AS post_not_updated FROM post WHERE status='published' AND post_desc NOT LIKE '%imp-related-reading%';
SELECT 'authors with no posts (old placeholder authors can be removed in the admin panel if unwanted)' AS check_name, slug FROM author WHERE id NOT IN (SELECT author_id FROM post WHERE author_id IS NOT NULL);
